import { useEffect, useState } from 'react'
import { Link } from 'react-router'
import { NoticeView } from '../../shared/ui/NoticeView'
import { useAction } from '../../shared/ui/useAction'
import { formatDate } from '../mission/format'
import { recommendationsApi } from './api'
import type { MaintenanceRecommendationResponse } from './types'

/** HU-14: preventive maintenance recommendations generated by the system (ADMIN only). */
export function RecommendationsPage() {
  const [recommendations, setRecommendations] = useState<MaintenanceRecommendationResponse[] | null>(null)
  const { notice, setNotice } = useAction()

  useEffect(() => {
    recommendationsApi.list().then(setRecommendations, (e: Error) => setNotice({ ok: false, text: e.message }))
  }, [setNotice])

  return (
    <section className="stack">
      <h1>Recomendaciones de mantenimiento</h1>
      <NoticeView notice={notice} />
      {recommendations?.length === 0 && <p className="empty">No hay recomendaciones de mantenimiento.</p>}
      {!!recommendations?.length && (
        <div className="table-wrap">
          <table>
            <thead><tr><th>Fecha</th><th>Dron</th><th>Motivo</th></tr></thead>
            <tbody>
              {recommendations.map((r) => (
                <tr key={r.id}>
                  <td>{formatDate(r.generatedAt)}</td>
                  <td><Link to={`/drones/${encodeURIComponent(r.droneCode)}`}>{r.droneCode}</Link></td>
                  <td>{r.reason}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  )
}
